package com.portfolio.features.resume.service;
import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
import com.portfolio.common.exception.NotFoundException; import com.portfolio.features.asset.entity.PortfolioAsset; import com.portfolio.features.asset.repository.PortfolioAssetRepository; import com.portfolio.features.asset.storage.StorageService; import com.portfolio.features.portfolio.entity.Portfolio; import com.portfolio.features.portfolio.service.PortfolioAccessService; import com.portfolio.features.resume.dto.ResumePreviewResponse; import com.portfolio.features.resume.extractor.ResumeTextExtractor; import com.portfolio.features.resume.parser.ResumeParser; import com.portfolio.features.user.entity.AppUser; import java.io.ByteArrayInputStream; import java.util.*; import org.junit.jupiter.api.Test;
class ResumeParsingServiceTest { private final PortfolioAccessService portfolios=mock(PortfolioAccessService.class); private final PortfolioAssetRepository assets=mock(PortfolioAssetRepository.class); private final StorageService storage=mock(StorageService.class); private final ResumeTextExtractor extractor=mock(ResumeTextExtractor.class); private final ResumeParser parser=mock(ResumeParser.class); private final ResumeParsingService service=new ResumeParsingService(portfolios,assets,storage,extractor,parser);
 @Test void parsesCurrentUsersResumeWithoutPersisting() throws Exception { AppUser user=new AppUser(); Portfolio portfolio=new Portfolio(); portfolio.setId(UUID.randomUUID()); PortfolioAsset asset=new PortfolioAsset();asset.setObjectKey("private/resume.pdf"); ResumePreviewResponse preview=mock(ResumePreviewResponse.class); when(portfolios.mine(user)).thenReturn(portfolio);when(assets.findByPortfolioIdAndAssetType(portfolio.getId(),"RESUME")).thenReturn(Optional.of(asset));when(storage.open(asset.getObjectKey())).thenReturn(new ByteArrayInputStream(new byte[0]));when(extractor.extract(any())).thenReturn("text");when(parser.parse("text")).thenReturn(preview);assertSame(preview,service.parseCurrentResume(user));verify(assets,never()).save(any()); }
 @Test void rejectsMissingResume() { AppUser user=new AppUser(); Portfolio portfolio=new Portfolio();portfolio.setId(UUID.randomUUID());when(portfolios.mine(user)).thenReturn(portfolio);when(assets.findByPortfolioIdAndAssetType(portfolio.getId(),"RESUME")).thenReturn(Optional.empty());assertThrows(NotFoundException.class,()->service.parseCurrentResume(user));verifyNoInteractions(storage,extractor,parser); }
}
